class Solution {
public:
    int rob(vector<int>& nums) {
        long long prev1 = 0; // best up to previous house
        long long prev2 = 0; // best up to house before previous
        for (int v : nums) {
            long long cur = max(prev1, prev2 + v);
            prev2 = prev1;
            prev1 = cur;
        }
        return static_cast<int>(prev1);
    }
};
